import React, { useEffect, useState } from "react";
import { useLocation } from "react-router-dom";
import SidebarMenu from "./SidebarMenu";

// Import CSS from local template folder
import "../../template/dist/css/adminlte.min.css";
import "../../template/plugins/fontawesome-free/css/all.min.css";
import "../../template/plugins/bootstrap/css/bootstrap.min.css";

// Import JS from local template folder
import "../../template/dist/js/adminlte.min.js";

const Layout = ({ children }) => {
  const location = useLocation();
  const hideSidebar =
    location.pathname.startsWith("/auth/login") || location.pathname === "/";

  const [module, setModule] = useState("");

  useEffect(() => {
    const path = location.pathname.split("/")[1];
    setModule(path);
  }, [location.pathname]);

  // Initialize treeview (optional)
  useEffect(() => {
    if (window.$) window.$(".nav-sidebar").treeview();
  }, []);

  const toggleSidebar = (e) => {
    e.preventDefault();
    if (window.$) {
      window.$("body").toggleClass("sidebar-collapse");
    }
  };

  return (
    <div className="wrapper hold-transition sidebar-mini layout-fixed">
      {/* Navbar */}
      {!hideSidebar && (
        <nav className="main-header navbar navbar-expand navbar-white navbar-light">
          <ul className="navbar-nav">
            <li className="nav-item">
              <a
                href="#"
                className="nav-link"
                role="button"
                onClick={toggleSidebar}
              >
                <i className="fas fa-bars"></i>
              </a>
            </li>
          </ul>
        </nav>
      )}

      {/* Sidebar */}
      {!hideSidebar && <SidebarMenu module={module} />}

      {/* Content */}
      <div className="content-wrapper p-3">
        <section className="content container-fluid">{children}</section>
      </div>
    </div>
  );
};

export default Layout;
